from typing import Any


def select_context(records: list[dict[str, Any]], query: str, limit: int) -> list[dict[str, Any]]:
    if not isinstance(records, list):
        raise ValueError("records must be a list")
    if not isinstance(query, str):
        raise ValueError("query must be a string")
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError("limit must be a non-negative integer")
    seen: set[str] = set()
    for record in records:
        if not isinstance(record, dict) or not {"id", "text", "metadata"}.issubset(record):
            raise ValueError("invalid record")
        if not isinstance(record["id"], str) or not record["id"] or record["id"] in seen:
            raise ValueError("record ids must be non-empty and unique")
        seen.add(record["id"])
        if not isinstance(record["text"], str) or not isinstance(record["metadata"], dict):
            raise ValueError("invalid record fields")

    query_tokens = {token.casefold() for token in query.split()}
    ranked = []
    for record in records:
        text_tokens = {token.casefold() for token in record["text"].split()}
        score = len(query_tokens & text_tokens)
        if score:
            item = dict(record)
            item["score"] = score
            ranked.append(item)
    ranked.sort(key=lambda item: (-item["score"], item["id"]))
    return ranked[:limit]
```

